"use client"

import { useEffect, useState, useRef } from "react"

export default function ProjectsSection() {
  const [isVisible, setIsVisible] = useState(false)
  const sectionRef = useRef(null)

  const projects = [
    {
      title: "Techzo",
      category: "BUSINESS",
      image: "https://ext.same-assets.com/498039404/1827805025.jpeg",
      position: "top-[10%] left-[20%]", // Top center on desktop
      delay: "delay-200",
      size: "w-[900px] h-[600px]",
      url: "https://techzo-demo.com",
    },
    {
      title: "Flakestake",
      category: "MARKETPLACE",
      image: "https://ext.same-assets.com/498039404/1730903789.jpeg",
      position: "top-[50%] left-[8%]", // Bottom left area on desktop
      delay: "delay-500",
      size: "w-[0px] h-[500px]",
      url: "https://flakestake-demo.com",
    },
    {
      title: "Rural Arena",
      category: "WEB DESIGN",
      image: "https://ext.same-assets.com/498039404/429890704.jpeg",
      position: "top-[44%] right-[5%]", // Middle right area on desktop
      delay: "delay-700",
      size: "w-[550px] h-[450px]",
      url: "https://ruralarena-demo.com",
    },
  ]

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.3 },
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    return () => observer.disconnect()
  }, [])

  return (
    <section
      ref={sectionRef}
      className="relative w-full lg:h-[1800px] h-auto overflow-hidden bg-black"
      style={{
        backgroundImage: `
          radial-gradient(circle, rgba(255,255,255,0.1) 1px, transparent 1px)
        `,
        backgroundSize: "20px 20px",
      }}
    >
      {/* Dotted mesh overlay */}
      <div
        className="absolute inset-0 opacity-30"
        style={{
          backgroundImage: `
            linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
            linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px)
          `,
          backgroundSize: "20px 20px",
        }}
      />

      {/* Section title */}
      <div
        className={`absolute lg:top-8 lg:left-8 top-6 left-6 transform transition-all duration-1000 z-10 ${
          isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"
        }`}
      >
        <h2 className="text-white lg:text-4xl text-3xl font-bold mb-2">Featured Work</h2>
        <p className="text-gray-400 lg:text-lg text-base">Explore our latest projects</p>
      </div>

      {/* Desktop Layout - Scattered positioning */}
      <div className="hidden lg:block">
        {projects.map((project, index) => (
          <div
            key={project.title}
            className={`absolute ${project.position} ${project.size} group cursor-pointer transform transition-all duration-1000 ease-out ${
              isVisible ? `translate-y-0 opacity-100 scale-100 ${project.delay}` : "translate-y-12 opacity-0 scale-95"
            }`}
          >
            {/* Project Card */}
            <div className="relative w-full h-full rounded-2xl overflow-hidden bg-gray-900 border border-gray-800 hover:border-gray-600 transition-all duration-500 hover:scale-105 hover:shadow-2xl hover:shadow-black/50">
              {/* Project Image */}
              <div className="relative w-full h-full overflow-hidden">
                <img
                  src={project.image || "/placeholder.svg"}
                  alt={project.title}
                  className="w-full h-full object-cover transition-all duration-700 group-hover:scale-110"
                />

                {/* Dark overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />

                {/* Hover overlay */}
                <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
              </div>

              {/* Navigation dots */}
              <div className="absolute bottom-16 left-6 flex gap-1">
                {[...Array(index + 3)].map((_, dotIndex) => (
                  <div
                    key={dotIndex}
                    className={`w-2 h-2 rounded-full transition-all duration-300 ${
                      dotIndex === 0 ? "bg-white" : "bg-white/30"
                    }`}
                  />
                ))}
              </div>

              {/* Project Info */}
              <div className="absolute bottom-16 left-6 right-20">
                <div className="space-y-2">
                  <h3 className="text-white text-2xl font-bold tracking-tight">{project.title}</h3>
                  <p className="text-gray-400 text-base font-medium tracking-wider uppercase">{project.category}</p>
                </div>
              </div>

              {/* Public Link Button - Only show if URL exists */}
              {project.url && (
                <a
                  href={project.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="absolute bottom-6 left-6 bg-white/10 backdrop-blur-sm border border-white/20 rounded-full px-4 py-2 text-white text-sm font-medium hover:bg-white/20 hover:scale-105 transition-all duration-300 group-hover:translate-x-1 group-hover:-translate-y-1"
                >
                  View Project
                </a>
              )}

              {/* Animated border on hover */}
              <div className="absolute inset-0 rounded-2xl border-2 border-white/0 group-hover:border-white/20 transition-all duration-500" />

              {/* Glow effect */}
              <div className="absolute -inset-1 bg-gradient-to-r from-blue-500/20 via-purple-500/20 to-teal-500/20 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 blur-xl -z-10" />
            </div>

            {/* Floating animation */}
            <style jsx>{`
              @keyframes float {
                0%, 100% { transform: translateY(0px) rotate(0deg); }
                33% { transform: translateY(-10px) rotate(1deg); }
                66% { transform: translateY(5px) rotate(-1deg); }
              }
              .group:hover {
                animation: float 6s ease-in-out infinite;
              }
            `}</style>
          </div>
        ))}
      </div>

      {/* Mobile Layout - Vertical Stack */}
      <div className="lg:hidden flex flex-col items-center justify-start pt-32 pb-16 px-4 space-y-8 min-h-screen">
        {projects.map((project, index) => (
          <div
            key={project.title}
            className={`w-full max-w-md group cursor-pointer transform transition-all duration-1000 ease-out ${
              isVisible ? `translate-y-0 opacity-100 scale-100 ${project.delay}` : "translate-y-12 opacity-0 scale-95"
            }`}
          >
            {/* Project Card */}
            <div className="relative w-full h-[400px] rounded-2xl overflow-hidden bg-gray-900 border border-gray-800 hover:border-gray-600 transition-all duration-500 hover:scale-105 hover:shadow-2xl hover:shadow-black/50">
              {/* Project Image */}
              <div className="relative w-full h-full overflow-hidden">
                <img
                  src={project.image || "/placeholder.svg"}
                  alt={project.title}
                  className="w-full h-full object-cover transition-all duration-700 group-hover:scale-110"
                />

                {/* Dark overlay */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />

                {/* Hover overlay */}
                <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
              </div>

              {/* Navigation dots */}
              <div className="absolute bottom-16 left-6 flex gap-1">
                {[...Array(index + 3)].map((_, dotIndex) => (
                  <div
                    key={dotIndex}
                    className={`w-2 h-2 rounded-full transition-all duration-300 ${
                      dotIndex === 0 ? "bg-white" : "bg-white/30"
                    }`}
                  />
                ))}
              </div>

              {/* Project Info */}
              <div className="absolute bottom-16 left-6 right-20">
                <div className="space-y-2">
                  <h3 className="text-white text-xl font-bold tracking-tight">{project.title}</h3>
                  <p className="text-gray-400 text-sm font-medium tracking-wider uppercase">{project.category}</p>
                </div>
              </div>

              {/* Public Link Button - Only show if URL exists */}
              {project.url && (
                <a
                  href={project.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="absolute bottom-6 left-6 bg-white/10 backdrop-blur-sm border border-white/20 rounded-full px-4 py-2 text-white text-sm font-medium hover:bg-white/20 hover:scale-105 transition-all duration-300 group-hover:translate-x-1 group-hover:-translate-y-1"
                >
                  View Project
                </a>
              )}

              {/* Animated border on hover */}
              <div className="absolute inset-0 rounded-2xl border-2 border-white/0 group-hover:border-white/20 transition-all duration-500" />

              {/* Glow effect */}
              <div className="absolute -inset-1 bg-gradient-to-r from-blue-500/20 via-purple-500/20 to-teal-500/20 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 blur-xl -z-10" />
            </div>

            {/* Mobile floating animation */}
            <style jsx>{`
              @keyframes mobileFloat {
                0%, 100% { transform: translateY(0px); }
                50% { transform: translateY(-5px); }
              }
              .group:hover {
                animation: mobileFloat 3s ease-in-out infinite;
              }
            `}</style>
          </div>
        ))}
      </div>

      {/* Background particles */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        {[...Array(20)].map((_, i) => (
          <div
            key={i}
            className="absolute w-1 h-1 bg-white/10 rounded-full animate-pulse"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              animationDelay: `${Math.random() * 3}s`,
              animationDuration: `${2 + Math.random() * 3}s`,
            }}
          />
        ))}
      </div>
    </section>
  )
}
